process DEEPVARIANT_POSTPROCESSVARIANTS {
    tag "$meta.id"
    label 'process_medium'

    //Conda is not supported at the moment
    container "docker.io/google/deepvariant:1.10.0"

    input:
    tuple val(meta), path(variant_calls_tfrecord_files), path(gvcf_tfrecords), path(small_model_calls), path(phase_inputs), path(intervals)
    tuple val(meta2), path(fasta)
    tuple val(meta3), path(fai)
    tuple val(meta4), path(gzi)

    output:
    tuple val(meta), path("${prefix}.vcf.gz")             , emit: vcf
    tuple val(meta), path("${prefix}.vcf.gz.{tbi,csi}")   , emit: vcf_index
    tuple val(meta), path("${prefix}.g.vcf.gz")           , emit: gvcf
    tuple val(meta), path("${prefix}.g.vcf.gz.{tbi,csi}") , emit: gvcf_index
    tuple val(meta), path("${prefix}.phased_reads_switches.tsv") , optional: true, emit: phased_reads_switches
    tuple val(meta), path("${prefix}.phased_reads_corrected.tsv"), optional: true, emit: phased_reads_corrected
    tuple val("${task.process}"), val('deepvariant'), eval("/opt/deepvariant/bin/run_deepvariant --version | sed 's/^.*version //'"), topic: versions, emit: versions_deepvariant

    when:
    task.ext.when == null || task.ext.when

    script:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "DEEPVARIANT module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    def args = task.ext.args ?: ''
    prefix = task.ext.prefix ?: "${meta.id}"

    def regions = intervals ? "--regions ${intervals}" : ""
    def variant_calls_tfrecord_name = variant_calls_tfrecord_files[0].name.replaceFirst(/-\d{5}-of-\d{5}/, "")

    def gvcf_matcher = gvcf_tfrecords[0].baseName =~ /^(.+)-\d{5}-of-(\d{5})$/
    if (!gvcf_matcher.matches()) {
        throw new IllegalArgumentException("tfrecord baseName '" + gvcf_tfrecords[0].baseName + "' doesn't match the expected pattern")
    }
    def gvcf_tfrecord_name = gvcf_matcher[0][1]
    def gvcf_shardCount = gvcf_matcher[0][2]
    // Reconstruct the logical name - ${tfrecord_name}.examples.tfrecord@${task.cpus}.gz
    def gvcf_tfrecords_logical_name = "${gvcf_tfrecord_name}@${gvcf_shardCount}.gz"

    // The following block determines whether the small model was used, and if so, adds the variant calls from it
    // to the argument --small_model_cvo_records.
    def small_model_arg = ""
    if (small_model_calls) {
        small_model_matcher = (small_model_calls[0].baseName =~ /^(.+)-\d{5}-of-(\d{5})$/)
        if (!small_model_matcher.matches()) {
            throw new IllegalArgumentException("tfrecord baseName '" + small_model_calls[0].baseName + "' doesn't match the expected pattern")
        }
        small_model_tfrecord_name = small_model_matcher[0][1]
        small_model_shardCount = small_model_matcher[0][2]
        // Reconstruct the logical name. Example: test_call_variant_outputs.examples.tfrecord@12.gz
        small_model_tfrecords_logical_name = "${small_model_tfrecord_name}@${small_model_shardCount}.gz"
        small_model_arg = "--small_model_cvo_records ${small_model_tfrecords_logical_name}"
    }

    // The following block determines whether phase info was outputted, and if so, adds the info from it
    // to the argument --phased_reads_input_path.
    def phased_inputs_arg = ""
    if (phase_inputs) {
        phase_inputs_matcher = (phase_inputs[0].baseName =~ /^(.+)-\d{5}-of-(\d{5})$/)
        if (!phase_inputs_matcher.matches()) {
            throw new IllegalArgumentException("read-phasing_debug baseName '" + phase_inputs[0].baseName + "' doesn't match the expected pattern")
        }
        phase_input_name = phase_inputs_matcher[0][1]
        phase_input_shardCount = phase_inputs_matcher[0][2]
        // Reconstruct the logical name. Example: test-read-phasing_debug@12.tsv
        phase_input_logical_name = "${phase_input_name}@${phase_input_shardCount}.tsv"
        phased_inputs_arg = "--phased_reads_input_path ${phase_input_logical_name} " +
            "--phased_reads_switches_output_path ${prefix}.phased_reads_switches.tsv " +
            "--phased_reads_corrected_output_path ${prefix}.phased_reads_corrected.tsv"
    }

    """
    export MPLCONFIGDIR=\$PWD/.matplotlib
    mkdir -p \$MPLCONFIGDIR

    /opt/deepvariant/bin/postprocess_variants \\
        ${args} \\
        --ref "${fasta}" \\
        --infile "${variant_calls_tfrecord_name}" \\
        --outfile "${prefix}.vcf.gz" \\
        --nonvariant_site_tfrecord_path "${gvcf_tfrecords_logical_name}" \\
        --gvcf_outfile "${prefix}.g.vcf.gz" \\
        ${regions} \\
        ${small_model_arg} \\
        ${phased_inputs_arg} \\
        --cpus $task.cpus

    """

    stub:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "DEEPVARIANT module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    prefix = task.ext.prefix ?: "${meta.id}"
    def touch_phased = phase_inputs ? "touch ${prefix}.phased_reads_switches.tsv ${prefix}.phased_reads_corrected.tsv" : ""
    """
    echo "" | gzip > ${prefix}.vcf.gz
    touch ${prefix}.vcf.gz.tbi
    echo "" | gzip > ${prefix}.g.vcf.gz
    touch ${prefix}.g.vcf.gz.tbi
    ${touch_phased}

    """
}

nextflow_process {

    name "Test Process DEEPVARIANT_POSTPROCESSVARIANTS"
    script "../main.nf"
    process "DEEPVARIANT_POSTPROCESSVARIANTS"
    config "./nextflow.config"

    tag "deepvariant/makeexamples"
    tag "deepvariant/callvariants"
    tag "deepvariant/postprocessvariants"
    tag "deepvariant"
    tag "modules"
    tag "modules_nfcore"

    test("homo_sapiens - wgs") {
        setup {
            run("DEEPVARIANT_MAKEEXAMPLES") {
                script "../../makeexamples/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true),
                        [],

                    ]
                    input[1] = [
                        [ id:'genome'],
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[2] = [
                        [ id:'genome'],
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                    ]
                    input[3] = [
                        [],[]
                    ]
                    input[4] = [
                        [],[]
                    ]
                    input[5] = false
                    """
                }
            }
            run("DEEPVARIANT_CALLVARIANTS") {
                script "../../callvariants/main.nf"
                process {
                    """
                    input[0] = DEEPVARIANT_MAKEEXAMPLES.out.examples
                    """
                }
            }
        }
        when {
            process {
                """
                input[0] = DEEPVARIANT_CALLVARIANTS.out.call_variants_tfrecords.join(
                    DEEPVARIANT_MAKEEXAMPLES.out.gvcf,
                    failOnMismatch: true
                ).join(
                    DEEPVARIANT_MAKEEXAMPLES.out.small_model_calls,
                    failOnMismatch: true
                ).join(
                    DEEPVARIANT_MAKEEXAMPLES.out.read_phase_inputs,
                    failOnMismatch: true
                ).map { meta, tf, gvcf, small_model_calls, read_phase_inputs -> [ meta, tf, gvcf, small_model_calls, read_phase_inputs, [] ] }
                input[1] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                input[3] = [
                    [],[]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("homo_sapiens - ont - phasing") {
        setup {
            run("DEEPVARIANT_MAKEEXAMPLES") {
                script "../../makeexamples/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/nanopore/bam/test.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/nanopore/bam/test.sorted.bam.bai', checkIfExists: true),
                        [],
                    ]
                    input[1] = [
                        [ id:'genome'],
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[2] = [
                        [ id:'genome'],
                        file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                    ]
                    input[3] = [
                        [],[]
                    ]
                    input[4] = [
                        [],[]
                    ]
                    input[5] = true
                    """
                }
            }
            run("DEEPVARIANT_CALLVARIANTS") {
                script "../../callvariants/main.nf"
                process {
                    """
                    input[0] = DEEPVARIANT_MAKEEXAMPLES.out.examples
                    """
                }
            }
        }
        when {
            params {
                makeexamples_args = '--checkpoint "/opt/models/ont_r104" --checkpoint_json "/opt/models/ont_r104/model.example_info.json" --call_small_model_examples --trained_small_model_path "/opt/smallmodels/ont/model.keras"'
                callvariants_args = '--checkpoint "/opt/models/ont_r104"'
            }
            process {
                """
                input[0] = DEEPVARIANT_CALLVARIANTS.out.call_variants_tfrecords.join(
                    DEEPVARIANT_MAKEEXAMPLES.out.gvcf,
                    failOnMismatch: true
                ).join(
                    DEEPVARIANT_MAKEEXAMPLES.out.small_model_calls,
                    failOnMismatch: true
                ).join(
                    DEEPVARIANT_MAKEEXAMPLES.out.read_phase_inputs,
                    failOnMismatch: true
                ).map { meta, tf, gvcf, small_model_calls, read_phase_inputs -> [ meta, tf, gvcf, small_model_calls, read_phase_inputs, [] ] }
                input[1] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                input[3] = [
                    [],[]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                // An empty switches file means that no phased reads were loaded
                { assert path(process.out.phased_reads_switches[0][1]).readLines().size() > 0 },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("homo_sapiens - wgs - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [],
                    [],
                    [],
                    [],
                    [],
                ]
                input[1] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'genome'],
                    file(params.modules_testdata_base_path + '/genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ]
                input[3] = [
                    [],[]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match("stub") }
            )
        }
    }

}

